var ReaderErrorCodes = []string{"storage_unavailable", "caller_unavailable", "identity_required", "wrong_user"}

var EditorErrorCodes = []string{"invalid_revision", "storage_unavailable", "caller_unavailable", "identity_required", "wrong_user"}

var ResourceActions = []string{"abstraction.config/key.read", "abstraction.config/user.replace"}

// Existing per-run overrides. Empty strings do not override file values.
type RunOverrides struct {
	NasStore   string
	Store      string
	LogSink    string
	LogService string
}

// Per-key provenance: machine/user file path, or environment/default with empty
// path.
type Origin struct {
	Rung string
	Path string
}

// Provenance for every configuration key, including default answers.
type Origins struct {
	NasStore   Origin
	Store      Origin
	LogSink    Origin
	LogService Origin
	Off        Origin
}

// Existing provider values and provenance. Empty values mean absence. Stamp
// follows values rather than provenance; paths are diagnostic configuration
// data, not permission to access a store.
type Snapshot struct {
	NasStore   string
	Store      string
	LogSink    string
	LogService string
	Off        map[string]string
	Origins    Origins
	Stamp      string
}

// User-rung overrides only. Empty values clear overrides; machine and run
// values never enter this record. The configuration backing-file path is
// selected by the service; path-valued settings grant no provider storage
// authority.
type UserSettings struct {
	NasStore   string
	Store      string
	LogSink    string
	LogService string
	Off        map[string]string
}

// Normalized user-rung content and an opaque content revision. A missing file
// yields empty values; unreadable or unsupported storage is refused. Revision
// may recur when identical content is restored.
type UserSnapshot struct {
	Values   UserSettings
	Revision string
}

// Applied returns the written snapshot. Conflict performs no write and returns
// the current snapshot. Forbidden reports an evaluated edit-policy refusal;
// unavailable reports that the edit-policy decision could not be obtained and
// may be retried. Both perform no storage access and carry empty values with an
// empty revision. No outcome merges settings implicitly.
type UserReplaceResult struct {
	Outcome  UserReplaceOutcome
	Snapshot UserSnapshot
}

// Latest effective configuration, with an opaque cursor bound to provider
// instance and explicit run overrides. snapshot carries a snapshot and new
// cursor; unchanged carries the original cursor and no snapshot. Other outcomes
// carry no snapshot and preserve the supplied cursor. Intermediate revisions
// may be coalesced; this is not an event history. A restarted provider or
// changed override binding gives gap and requires an explicit empty-cursor
// restart.
type ConfigObservation struct {
	Outcome  ConfigObservationOutcome
	Cursor   string
	Snapshot *Snapshot
}

// The tag carries value presence, including false, zero and empty
// text/list/map. Every payload other than the field selected by kind is zero.
// The runtime validates this invariant on changes and stored values; generated
// generic client parsers apply the same invariant. Unset is an absent
// Entry.value or Change.set, never a zero payload.
type Value struct {
	Kind       ValueKind
	Boolean    bool
	Integer    int64
	Bytes      int64
	DurationMs int64
	Text       string
	Choice     string
	TextList   []string
	TextMap    map[string]string
}

type ConfigSource struct {
	Location Location
	Path     string
}

// Per-key effective location and state. Paths are diagnostic and grant no
// storage access. A lockable key set in a trusted machine file is locked and
// wins over user and process values. Shadowed lists farther settings that also
// supplied the key.
type KeyOrigin struct {
	Location Location
	Path     string
	State    KeyState
	Reason   string
	Shadowed []ConfigSource
}

// A known key. Absent value means unset, with its catalogue default applying
// when present. Unknown or unauthorized keys occur only in ReadResult.refused.
type Entry struct {
	Key    string
	Value  *Value
	Origin KeyOrigin
}

type ValueRange struct {
	Min int64
	Max int64
}

// Definition-owned key metadata from keys.json, validated by this record's
// generated schema and emitted as one bounded catalogue constant. Range applies
// to integer, bytes and duration; choices to choice. No key is a wire record
// field. default_description explains an existing provider-computed default.
type KeyDescriptor struct {
	Key                string
	Kind               ValueKind
	Default            *Value
	Range              *ValueRange
	Choices            []string
	Presets            []Value
	Description        string
	Group              string
	Apply              ApplyMode
	Lockable           bool
	LowestLocation     Location
	Deprecated         string
	DefaultDescription string
	AllowsUnlimited    bool
}

// Set one typed user value or unset it when set is absent. A batch applies all
// changes or none under its compared user-content revision.
type Change struct {
	Key string
	Set *Value
}

type KeyRefusal struct {
	Key     string
	Reason  KeyRefusalReason
	Refusal *oaImported0
}

// A bounded key-specific diagnostic. It contains no supplied value or
// credential. Locked edits use locked:machine; invalid edits name unknown_key,
// wrong_kind, out_of_range or invalid_value.
type KeyProblem struct {
	Key    string
	Reason string
}

// A bounded display-only excerpt of an ignored stored member name. The
// zero-based offset locates its original bytes; the excerpt is sanitized UTF-8,
// at most 64 bytes, with an ellipsis when cut. It is never a key, selector or
// authority.
type IgnoredField struct {
	Offset      int64
	NameExcerpt string
	Reason      IgnoredFieldReason
	Source      ConfigSource
}

// Successful entries and per-key refusals are disjoint. revision is the
// effective-content digest including provenance/state. A malformed known stored
// value is ignored with invalid_value and the default value. An unparseable
// record gives corrupt with its zero-based first failing byte offset; outcome
// carries offset presence including zero. Storage I/O gives unavailable.
// Non-read outcomes disclose no entries or revision.
type ReadResult struct {
	Outcome        ReadOutcome
	Entries        []Entry
	Revision       string
	Refused        []KeyRefusal
	Problem        *KeyProblem
	CorruptOffset  int64
	IgnoredFields  []IgnoredField
	IgnoredOmitted int64
	CorruptSource  *ConfigSource
	Refusal        *oaImported0
}

// Only persisted user values, with a normalized-content revision distinct from
// the effective revision. Legacy @1-only fields are preserved in the same store
// and are absent from this projection.
type UserSnapshotV2 struct {
	Entries  []Entry
	Revision string
}

type UserReadResultV2 struct {
	Outcome       ReadOutcome
	Snapshot      *UserSnapshotV2
	Problem       *KeyProblem
	CorruptOffset int64
	Refusal       *oaImported0
}

// Applied and conflict carry the current user snapshot; every other outcome
// omits snapshot and discloses no user state. A locked key is not_permitted
// with locked:machine. Unknown/wrong-kind/out-of-range values are invalid.
// Refusal writes nothing. A canceled wait leaves outcome unresolved; reread
// before retrying.
type UserReplaceResultV2 struct {
	Outcome       ReplaceOutcome
	Snapshot      *UserSnapshotV2
	Refused       []KeyProblem
	CorruptOffset int64
	Refusal       *oaImported0
}

// One latest effective snapshot. Values, lock state and restart-pending state
// invalidate the revision. No process overrides cross the wire or bind this
// cursor. Restart gives gap. Unchanged carries the original cursor and no
// snapshot.
type ConfigObservationV2 struct {
	Outcome       ObservationOutcomeV2
	Cursor        string
	Snapshot      *ReadResult
	Problem       *KeyProblem
	CorruptOffset int64
	CorruptSource *ConfigSource
	Refusal       *oaImported0
	AgeMs         *int64
	Cause         string
}

// read carries the complete bounded catalogue; every refusal carries an empty
// list. CFG-S3 declares the bounded-catalogue paging divergence.
type DescribeResult struct {
	Outcome     ReadOutcome
	Descriptors []KeyDescriptor
	Refusal     *oaImported0
}

// The one refusal record every OA service carries beside a refusing outcome
// (RIGHTS-E3; conventions CONV-E4). source names the authority that refused:
// rights, credentials, license, terms, identity or os. decision is denied for
// an explicit refusal, not_granted where no rule permits, and person_only where
// only the person may answer the question. ask says whether asking can change
// the answer: available, or none. action is the exact registered
// <owner>/<name>; question the pending question's id; credential the
// credential's name; retry_after_ms the earliest useful retry in milliseconds,
// omitted when zero. Stop asking is denied with ask none. Current carriers
// include config@2, messages@1, registry@3, endpoint@2 and chat@3, declared in
// config.thrift, messages.thrift, registration.thrift and inference.thrift.
// Other services adopt it in their scheduled versions.
type EndpointRefusalDetail struct {
	Source       EndpointRefusalSource
	Decision     EndpointRefusalDecision
	Ask          EndpointRefusalAsk
	Action       string
	Question     string
	Credential   string
	RetryAfterMs int64
}

// Producer assertion validated by the runtime. Kind is the governed open
// build-time vocabulary <owner>/<name>, not a display string or an authority
// claim. copy identifies one copy within the kind. reason follows D87
// domain:word:detail as open display text. checked is the producer's claimed
// check time. Custom/unknown copies are unverified; readiness remains
// independent. No runtime kind-registration method is introduced.
type EndpointProducerCheck struct {
	Kind    string
	Copy    string
	State   EndpointProducerCheckState
	Reason  string
	Checked string
}

// endpoint@2 service observation. definition_hash is sha256: plus64 lowercase
// hex over this service version's canonical wire form (CONV-V2), verified by
// the definition-hash owner. reason retains readiness errors and is empty when
// ready. capabilities remain display-only. Program-level producer checks belong
// to EndpointDescription and are independent of service readiness.
type EndpointServiceState struct {
	Service        string
	Readiness      EndpointServiceReadiness
	Reason         string
	Guarantees     []string
	Capabilities   map[string]string
	DefinitionHash string
}

// Complete endpoint@2 description with each advertised service's definition
// hash and one program-level producer-check list. Checks are independent of
// service readiness; absence means unobserved, never verified.
// Forbidden/unavailable authority refusals carry the single Rights-owned
// EndpointRefusalDetail; other outcomes omit it. Unsupported carries the
// existing bounded reason with D87 unsupported:not_implemented words; no closed
// staged-reason vocabulary is frozen. Non-described replies disclose no
// program/version/services/checks. Endpoint@1 and its closed
// EndpointDescription/EndpointServiceState remain unchanged. The compact value
// ceiling excluding insignificant JSON whitespace is IPC-F1; an oversized whole
// reply is unavailable/bound:reply_bytes without truncation.
type EndpointDescription struct {
	Outcome  EndpointDescriptionOutcome
	Program  string
	Version  string
	Services []EndpointServiceState
	Refusal  *EndpointRefusalDetail
	Reason   string
	Checks   []EndpointProducerCheck
}

type EndpointDescriptionResult struct {
	Value EndpointDescription
}

