func encValue(out []byte, v *Value, depth int) []byte {
	encodedCounter := compactEncodedCounter{start: len(out), pos: len(out)}
	if n := len(v.Text); n > 4096 {
		panic(&Refusal{Word: "bad_value", Offset: 0})
	}
	for _, c := range v.Text {
		if c < 0x20 || c >= 0x7f && c <= 0x9f {
			panic(&Refusal{Word: "bad_value", Offset: 0})
		}
	}
	if n := len(v.Choice); n != 0 && (n < 1 || n > 64) {
		panic(&Refusal{Word: "bad_value", Offset: 0})
	}
	for i := 0; i < len(v.Choice); i++ {
		if c := v.Choice[i]; !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '.' || c == '-') {
			panic(&Refusal{Word: "bad_value", Offset: 0})
		}
	}
	if n := len(v.TextList); n > 128 {
		panic(&Refusal{Word: "bad_value", Offset: 0})
	}
	for _, oaElement := range v.TextList {
		if n := len(oaElement); n < 1 || n > 128 {
			panic(&Refusal{Word: "bad_value", Offset: 0})
		}
	}
	for _, oaElement := range v.TextList {
		for _, c := range oaElement {
			if c < 0x20 || c >= 0x7f && c <= 0x9f {
				panic(&Refusal{Word: "bad_value", Offset: 0})
			}
		}
	}
	if n := len(v.TextMap); n > 8 {
		panic(&Refusal{Word: "bad_value", Offset: 0})
	}
	for oaElement := range v.TextMap {
		if n := len(oaElement); n < 1 || n > 64 {
			panic(&Refusal{Word: "bad_value", Offset: 0})
		}
	}
	for oaElement := range v.TextMap {
		for i := 0; i < len(oaElement); i++ {
			if c := oaElement[i]; !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '.' || c == '-') {
				panic(&Refusal{Word: "bad_value", Offset: 0})
			}
		}
	}
	for _, oaElement := range v.TextMap {
		if n := len(oaElement); n > 512 {
			panic(&Refusal{Word: "bad_value", Offset: 0})
		}
	}
	for _, oaElement := range v.TextMap {
		for _, c := range oaElement {
			if c < 0x20 || c >= 0x7f && c <= 0x9f {
				panic(&Refusal{Word: "bad_value", Offset: 0})
			}
		}
	}
	if !(v.Kind).Known() {
		panic(&Refusal{Word: "bad_enum", Offset: 0})
	}
	out = append(out, '{')
	out = append(out, '\n')
	out = pad(out, depth+1)
	out = esc(out, "kind")
	out = append(out, ':', ' ')
	out = esc(out, v.Kind.String())
	encodedCounter.check(out, 262144)
	if v.Boolean {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "boolean")
		out = append(out, ':', ' ')
		if v.Boolean {
			out = append(out, 't', 'r', 'u', 'e')
		} else {
			out = append(out, 'f', 'a', 'l', 's', 'e')
		}
	}
	encodedCounter.check(out, 262144)
	if v.Integer != 0 {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "integer")
		out = append(out, ':', ' ')
		out = num(out, v.Integer)
	}
	encodedCounter.check(out, 262144)
	if v.Bytes != 0 {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "bytes")
		out = append(out, ':', ' ')
		out = num(out, v.Bytes)
	}
	encodedCounter.check(out, 262144)
	if v.DurationMs != 0 {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "duration_ms")
		out = append(out, ':', ' ')
		out = num(out, v.DurationMs)
	}
	encodedCounter.check(out, 262144)
	if v.Text != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "text")
		out = append(out, ':', ' ')
		out = esc(out, v.Text)
	}
	encodedCounter.check(out, 262144)
	if v.Choice != "" {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "choice")
		out = append(out, ':', ' ')
		out = esc(out, v.Choice)
	}
	encodedCounter.check(out, 262144)
	if len(v.TextList) != 0 {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "text_list")
		out = append(out, ':', ' ')
		out = strs(out, v.TextList, depth+1)
	}
	encodedCounter.check(out, 262144)
	if len(v.TextMap) != 0 {
		out = append(out, ',')
		out = append(out, '\n')
		out = pad(out, depth+1)
		out = esc(out, "text_map")
		out = append(out, ':', ' ')
		out = strmap(out, v.TextMap, depth+1)
	}
	encodedCounter.check(out, 262144)
	out = append(out, '\n')
	out = pad(out, depth)
	out = append(out, '}')
	encodedCounter.check(out, 262144)
	return out
}

