// ObservePages yields one bounded observation per request. A later range resumes
// at the last successful cursor after an error; no call is retried inside a request.
func (c *ConfigObserverV2Client) ObservePages(cursor string, waitMs int64) func(func(ConfigObservationV2, error) bool) {
	return func(_observeYield func(ConfigObservationV2, error) bool) {
		if waitMs < 0 || waitMs > 30000 {
			var _observePage ConfigObservationV2
			_observeYield(_observePage, &ServiceError{Code: "invalid_request", Message: "observe wait_ms is 0..30000"})
			return
		}
		for {
			_observePage, _observeErr := c.Observe(cursor, waitMs)
			if _observeErr == nil {
				cursor = _observePage.Cursor
			}
			if !_observeYield(_observePage, _observeErr) || _observeErr != nil {
				return
			}
		}
	}
}

