func ValidateConfigValue(v *Value) error {
	if v == nil || !((v.Kind.String() == "unlimited" || v.Kind.String() == "boolean" || v.Kind.String() == "integer" || v.Kind.String() == "bytes" || v.Kind.String() == "duration" || v.Kind.String() == "text" || v.Kind.String() == "choice" || v.Kind.String() == "text_list" || v.Kind.String() == "text_map") && (v.Kind.String() == "boolean" || !v.Boolean) && (v.Kind.String() == "integer" || v.Integer == 0) && (v.Kind.String() == "bytes" || v.Bytes == 0) && (v.Kind.String() == "duration" || v.DurationMs == 0) && (v.Kind.String() == "text" || v.Text == "") && (v.Kind.String() == "choice" || v.Choice == "") && (v.Kind.String() == "text_list" || len(v.TextList) == 0) && (v.Kind.String() == "text_map" || len(v.TextMap) == 0)) {
		return &Refusal{Word: "bad_value"}
	}
	data, err := ToJSON(v)
	if err != nil {
		return err
	}
	var checked Value
	return FromJSON(data, &checked)
}

